sheets.global:
@layer anm-global {
@font-face { font-family: AnimusTestFont; src: url('animus-asset:@animus-ui/test-ds/assets/test-font.woff2') format('woff2'); font-display: swap; }

*, *::before, *::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  background-color: var(--color-background);
  --current-bg: var(--color-background);
  color: var(--color-text);
  font-family: system-ui, sans-serif;
}
@keyframes animus-kf-1x7guim {
  0% {
    opacity: 0;
    background-color: var(--color-background);
    --current-bg: var(--color-background);
  }
  100% {
    opacity: 1;
    background-color: var(--color-surface);
    --current-bg: var(--color-surface);
  }
}

@keyframes animus-kf-1yqv0zl {
  0%, 100% {
    transform: scale(1);
